const rnd=(seed)=>{let s=seed;return()=>((s=(s*9301+49297)%233280)/233280)};
window.H={rnd:rnd,n:0};
H.uid=(p)=>p+(H.n++);
H.SV=(inner)=>`<svg class=layer viewBox='0 0 1080 1920' width=1080 height=1920>${inner}</svg>`;
H.Z1={torso:10,head:16,uaL:-80,laL:-8,uaR:-100,laR:-12,ulL:-20,llL:22,ulR:16,llR:0};
H.Z2={torso:10,head:16,uaL:-80,laL:-8,uaR:-100,laR:-12,ulL:16,llL:0,ulR:-20,llR:22};
H.ZB={torso:0,head:10,uaL:155,laL:25,uaR:-155,laR:-25,ulL:4,llL:0,ulR:-4,llR:0};
H.ZB2={torso:0,head:10,uaL:118,laL:35,uaR:-118,laR:-35,ulL:4,llL:0,ulR:-4,llR:0};
H.zomb=(id,x,y,s,flip,tone)=>R.stick(id,{x:x,y:y,s:s,flip:!!flip,color:tone||'#7d9a70',stroke:'#0f1a12',face:'shock',w:22});
H.zwalk=(tl,id,toX,t,dur,step)=>{step=step||0.5;let k=0;for(let tt=t;tt<t+dur-0.01;tt+=step,k++)R.pose(tl,id,k%2?H.Z2:H.Z1,tt,step,'sine.inOut');R.move(tl,id,{x:toX},t,dur);};
H.flash=(tl,p,S,D,every)=>{every=every||0.28;let k=0;for(let t=S;t<S+D;t+=every,k++){tl.set('#'+p+'a',{opacity:k%2?0.15:1},t);tl.set('#'+p+'b',{opacity:k%2?1:0.15},t);tl.set('#'+p+'ga',{opacity:k%2?0.1:0.9},t);tl.set('#'+p+'gb',{opacity:k%2?0.9:0.1},t);}};
H.cart=(x,y,s)=>`<g transform='translate(${x},${y}) scale(${s})'><polygon points='-110,-150 120,-150 95,-60 -85,-60' fill='#cfd3da' opacity='.92' stroke='#6a707a' stroke-width='6'/><g stroke='#6a707a' stroke-width='4'><line x1='-60' y1='-150' x2='-48' y2='-60'/><line x1='-10' y1='-150' x2='-8' y2='-60'/><line x1='40' y1='-150' x2='32' y2='-60'/><line x1='90' y1='-150' x2='72' y2='-60'/><line x1='-100' y1='-105' x2='108' y2='-105'/></g><line x1='-110' y1='-150' x2='-150' y2='-200' stroke='#e03a2b' stroke-width='12' stroke-linecap='round'/><line x1='-168' y1='-200' x2='-124' y2='-200' stroke='#e03a2b' stroke-width='14' stroke-linecap='round'/><line x1='-70' y1='-60' x2='-70' y2='-44' stroke='#6a707a' stroke-width='6'/><line x1='80' y1='-60' x2='80' y2='-44' stroke='#6a707a' stroke-width='6'/><circle cx='-70' cy='-30' r='16' fill='#222'/><circle cx='80' cy='-30' r='16' fill='#222'/></g>`;
H.fence=(x,y,w,h)=>{const id=H.uid('mh');let s=`<defs><pattern id='${id}' width='22' height='22' patternUnits='userSpaceOnUse'><path d='M0 0 L22 22 M22 0 L0 22' stroke='#a9b2bb' stroke-width='2'/></pattern></defs><rect x='${x}' y='${y}' width='${w}' height='${h}' fill='url(#${id})' opacity='.75'/>`;
 for(let px=x;px<=x+w;px+=130)s+=`<rect x='${px-5}' y='${y-14}' width='10' height='${h+14}' fill='#59616b'/>`;
 s+=`<rect x='${x}' y='${y}' width='${w}' height='6' fill='#59616b'/>`;
 let pts='';for(let i=0;i<=w/16;i++)pts+=`${x+i*16},${y-8-(i%2)*14} `;
 s+=`<polyline points='${pts}' fill='none' stroke='#c9ced6' stroke-width='3'/>`;return s;};
H.aisle=(seed)=>{
 const r=rnd(seed);
 const cols=['#e8e6df','#3b6fb6','#f2c230','#c93a2b','#8c8f96','#f6f1e3','#2f8f55','#d9d2c0'];
 const wall=(side)=>{
  const P=(u,v)=>{const x=side<0?380*u:1080-380*u;const yt=200+560*u,yb=1920-880*u;return [x,yt+(yb-yt)*v];};
  const Q=(u0,u1,v0,v1,f)=>`<polygon points='${P(u0,v0)} ${P(u1,v0)} ${P(u1,v1)} ${P(u0,v1)}' fill='${f}'/>`;
  let s=Q(0,1,0,1,'#a8480c');
  for(let lv=0;lv<5;lv++){const v1=0.2+lv*0.19;let u=0.02;
   while(u<0.96){const u1=Math.min(0.97,u+0.05+r()*0.1);const h=0.07+r()*0.09;s+=Q(u,u1-0.006,v1-h,v1,cols[Math.floor(r()*cols.length)]);u=u1+0.01+r()*0.02;}
   s+=Q(0,1,v1,v1+0.016,'#f26a1b');}
  for(let k=0;k<=8;k++)s+=Q(k/8-0.005,k/8+0.005,0,1,'#f26a1b');
  return s;};
 let lights='';
 for(const u of [0.08,0.26,0.44,0.6,0.74]){const u2=u+0.06;const w1=1080-760*u,w2=1080-760*u2;const y1=200+560*u,y2=200+560*u2;
  lights+=`<polygon points='${540-0.22*w1},${y1} ${540+0.22*w1},${y1} ${540+0.22*w2},${y2} ${540-0.22*w2},${y2}' fill='#fff6d8'/>`;}
 let beams='';
 for(let k=1;k<9;k++){const u=k/9;const y=200+560*u;beams+=`<line x1='${380*u}' y1='${y}' x2='${1080-380*u}' y2='${y}' stroke='#4a4e57' stroke-width='${14*(1-u)+2}'/>`;}
 let fl='';
 for(let k=-6;k<=6;k++){fl+=`<line x1='${540+k*40}' y1='1040' x2='${540+k*200}' y2='1920' stroke='#77746e' stroke-width='3'/>`;}
 const gid=H.uid('fg');
 return `<defs><linearGradient id='${gid}' x1='0' y1='0' x2='0' y2='1'><stop offset='0' stop-color='#6e6b65'/><stop offset='1' stop-color='#a9a69e'/></linearGradient></defs><rect width='1080' height='1920' fill='#23252b'/><rect x='380' y='760' width='320' height='280' fill='#e6dfcc'/><polygon points='0,1920 1080,1920 700,1040 380,1040' fill='url(#${gid})'/>${fl}<polygon points='0,0 1080,0 1080,200 700,760 380,760 0,200' fill='#2a2c33'/>${beams}${wall(-1)}${wall(1)}<g class='lt'>${lights}</g>`;
};
H.police=(p,night,litP,seed)=>{
 const r=rnd(seed);
 const win=(x,y)=>{const on=r()<litP;return `<rect x='${x}' y='${y}' width='64' height='76' fill='${on?'#ffd36b':'#12151b'}' stroke='#20242c' stroke-width='6'/>`;};
 let s=`<defs><radialGradient id='${p}rr'><stop offset='0' stop-color='#ff2a2a' stop-opacity='.8'/><stop offset='1' stop-color='#ff2a2a' stop-opacity='0'/></radialGradient><radialGradient id='${p}rb'><stop offset='0' stop-color='#2a6cff' stop-opacity='.8'/><stop offset='1' stop-color='#2a6cff' stop-opacity='0'/></radialGradient></defs>`;
 s+=`<g id='${p}bld'><rect x='90' y='800' width='660' height='540' fill='${night?'#2d323d':'#5b6270'}'/><rect x='70' y='770' width='700' height='40' fill='${night?'#20242c':'#434956'}'/>`;
 for(let i=0;i<5;i++){s+=win(130+i*120,830)+win(130+i*120,1030);}
 s+=`<rect x='250' y='925' width='360' height='85' fill='#1f3a8a'/><text x='430' y='988' text-anchor='middle' font-family='Anton' font-size='66' fill='#fff' letter-spacing='8'>POLICE</text>`;
 const dl=litP>0.6?'#ffe9a8':'#0f1218';
 s+=`<rect x='366' y='1124' width='128' height='216' fill='#161a21' stroke='#20242c' stroke-width='8'/><rect x='376' y='1134' width='50' height='200' fill='${dl}'/><rect x='434' y='1134' width='50' height='200' fill='${dl}'/><rect x='60' y='1340' width='720' height='30' fill='#80858f'/>`;
 s+=`<line x1='700' y1='640' x2='700' y2='780' stroke='#9aa0aa' stroke-width='8'/><polygon points='704,646 780,662 704,684' fill='#2f4fa8'/></g>`;
 s+=`<ellipse cx='385' cy='1530' rx='200' ry='18' fill='#000' opacity='.4'/><rect x='215' y='1440' width='340' height='80' rx='24' fill='#15181f'/><polygon points='285,1442 330,1388 470,1388 515,1442' fill='#e9ecf1'/><rect x='215' y='1478' width='340' height='14' fill='#e9ecf1'/><circle cx='290' cy='1520' r='26' fill='#0a0a0c'/><circle cx='480' cy='1520' r='26' fill='#0a0a0c'/>`;
 s+=`<circle id='${p}ga' cx='375' cy='1378' r='190' fill='url(#${p}rr)'/><circle id='${p}gb' cx='435' cy='1378' r='190' fill='url(#${p}rb)'/><rect id='${p}a' x='350' y='1368' width='50' height='20' fill='#ff2a2a'/><rect id='${p}b' x='410' y='1368' width='50' height='20' fill='#2a6cff'/>`;
 return s;};

